const express = require('express');
const crypto = require('crypto');
const multer = require('multer');
const sharp = require('sharp');
const session = require('express-session');
const fs = require('fs');
const path = require('path');

const app = express();
const upload = multer({ dest: '/tmp/uploads/', limits: { fileSize: 10 * 1024 * 1024 } });

const ENCRYPTION_KEY = crypto.randomBytes(32);
const STORAGE_DIR = path.resolve('/var/app/encrypted_images');

app.use(express.json());
app.use(express.urlencoded({ extended: false }));
app.use(session({
  secret: crypto.randomBytes(64).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict' }
}));

function encryptBuffer(buffer) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  const encrypted = Buffer.concat([cipher.update(buffer), cipher.final()]);
  const tag = cipher.getAuthTag();
  return { iv, encrypted, tag };
}

function decryptBuffer(iv, encrypted, tag) {
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(encrypted), decipher.final()]);
}

function requireAuth(req, res, next) {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

class CSRFProtection {
  constructor() {
    this.tokenStore = new Map();
  }

  generateToken(sessionId) {
    const token = crypto.randomBytes(32).toString('hex');
    this.tokenStore.set(sessionId, { token, timestamp: Date.now() });
    return token;
  }

  validateToken(sessionId, token) {
    const stored = this.tokenStore.get(sessionId);
    if (!stored) return false;
    const TOKEN_MAX_AGE = 3600000;
    if (Date.now() - stored.timestamp > TOKEN_MAX_AGE) {
      this.tokenStore.delete(sessionId);
      return false;
    }
    return crypto.timingSafeEqual(
      Buffer.from(stored.token, 'hex'),
      Buffer.from(token, 'hex')
    );
  }

  middleware() {
    return (req, res, next) => {
      if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
        return next();
      }
      const contentType = req.headers['content-type'] || '';
      if (contentType.startsWith('multipart/form-data')) {
        return next();
      }
      const token = req.headers['x-csrf-token'] || req.body._csrf;
      if (!token || !this.validateToken(req.session.id, token)) {
        return res.status(403).json({ error: 'Invalid CSRF token' });
      }
      next();
    };
  }
}

const csrf = new CSRFProtection();
app.use(csrf.middleware());

app.get('/api/csrf-token', requireAuth, (req, res) => {
  const token = csrf.generateToken(req.session.id);
  res.json({ token });
});

app.post('/api/images/upload', requireAuth, upload.single('image'), async (req, res) => {
  try {
    if (!req.file) return res.status(400).json({ error: 'No file provided' });
    const allowedMimes = ['image/jpeg', 'image/png', 'image/webp'];
    if (!allowedMimes.includes(req.file.mimetype)) {
      fs.unlinkSync(req.file.path);
      return res.status(400).json({ error: 'Invalid file type' });
    }
    const rawBuffer = fs.readFileSync(req.file.path);
    fs.unlinkSync(req.file.path);
    const processed = await sharp(rawBuffer)
      .resize({ width: 1920, height: 1080, fit: 'inside', withoutEnlargement: true })
      .removeAlpha()
      .toFormat('png')
      .toBuffer();
    const { iv, encrypted, tag } = encryptBuffer(processed);
    const imageId = crypto.randomBytes(16).toString('hex');
    const storagePath = path.join(STORAGE_DIR, `${imageId}.enc`);
    const metadata = { iv: iv.toString('hex'), tag: tag.toString('hex'), owner: req.session.userId };
    fs.writeFileSync(storagePath, encrypted);
    fs.writeFileSync(`${storagePath}.meta`, JSON.stringify(metadata));
    res.json({ imageId, message: 'Image uploaded and encrypted' });
  } catch (err) {
    res.status(500).json({ error: 'Processing failed' });
  }
});

app.post('/api/images/:id/transform', requireAuth, async (req, res) => {
  try {
    const imageId = req.params.id.replace(/[^a-f0-9]/g, '');
    const storagePath = path.join(STORAGE_DIR, `${imageId}.enc`);
    if (!fs.existsSync(storagePath)) return res.status(404).json({ error: 'Not found' });
    const metadata = JSON.parse(fs.readFileSync(`${storagePath}.meta`, 'utf8'));
    if (metadata.owner !== req.session.userId) return res.status(403).json({ error: 'Forbidden' });
    const encrypted = fs.readFileSync(storagePath);
    const decrypted = decryptBuffer(
      Buffer.from(metadata.iv, 'hex'), encrypted, Buffer.from(metadata.tag, 'hex')
    );
    const { operation, params } = req.body;
    let pipeline = sharp(decrypted);
    if (operation === 'rotate') pipeline = pipeline.rotate(parseInt(params.angle) || 0);
    else if (operation === 'blur') pipeline = pipeline.blur(Math.min(parseFloat(params.sigma) || 1, 10));
    else if (operation === 'grayscale') pipeline = pipeline.grayscale();
    else return res.status(400).json({ error: 'Unknown operation' });
    const result = await pipeline.toFormat('png').toBuffer();
    const { iv, encrypted: enc, tag } = encryptBuffer(result);
    fs.writeFileSync(storagePath, enc);
    metadata.iv = iv.toString('hex');
    metadata.tag = tag.toString('hex');
    fs.writeFileSync(`${storagePath}.meta`, JSON.stringify(metadata));
    res.json({ message: 'Transform applied' });
  } catch (err) {
    res.status(500).json({ error: 'Transform failed' });
  }
});

app.delete('/api/images/:id', requireAuth, async (req, res) => {
  try {
    const imageId = req.params.id.replace(/[^a-f0-9]/g, '');
    const storagePath = path.join(STORAGE_DIR, `${imageId}.enc`);
    if (!fs.existsSync(storagePath)) return res.status(404).json({ error: 'Not found' });
    const metadata = JSON.parse(fs.readFileSync(`${storagePath}.meta`, 'utf8'));
    if (metadata.owner !== req.session.userId) return res.status(403).json({ error: 'Forbidden' });
    fs.unlinkSync(storagePath);
    fs.unlinkSync(`${storagePath}.meta`);
    res.json({ message: 'Image deleted' });
  } catch (err) {
    res.status(500).json({ error: 'Delete failed' });
  }
});

module.exports = app;
